glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  vec3 col = c.rgb * mix(vec3(1.0), vec3(0.8, 0.85, 0.95), uAmount);
  vec2 p = vec2((uv.x + uv.y * 0.15) * 70.0 * uRatio, uv.y * 6.0 + uTime * 9.0);
  vec2 id = floor(p);
  vec2 f = fract(p);
  float drop = step(0.9, hash(vec2(id.x, id.y))) * smoothstep(0.5, 0.0, abs(f.x - 0.5) * 6.0) * smoothstep(0.0, 0.4, f.y) * smoothstep(1.0, 0.6, f.y);
  col += vec3(0.55, 0.6, 0.7) * drop * uAmount;
  return vec4(col, c.a);
}
